mapper.select:
SELECT FP.*, FP.CCY,NVL(FPA.FACE_VALUE,100) AS faceValue, FPT.TYPE_11 type11, FPT.TYPE_12 type12, FPA.DEAL_MODE dealMode, FPA.INVESTMENT_CYCLE investmentCycle, FPA.TERM_TYPE termType /*FPA.PRODUCT_TYPE prodType,*/ /*FPA.MIN_PRODUCT_HOLD minProductHold*/ FROM FIN_PRODUCT FP INNER JOIN FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID=FPA.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=0
FP.FINPROD_ID in
#{item}

SELECT CLOSE_PRICE FROM (
select
MID_PRICE,rank() OVER(PARTITION BY EXCHARGE_CODE ORDER BY TRADE_DATE DESC ) AS rowno
from MST_EXCHARGE_QUOTE  WHERE TRADE_DATE <= #{valDate, jdbcType=DATE}
AND QUOT_CYY = #{quotCcy}
AND BASIS_CYY = #{basisCcy}
) WHERE ROWNO =1

SELECT SEC_ID,PRICE,NETPRICE,M_DURATION,BPYIELD,LAST_PERIOD FROM (
select
MVI.SEC_ID,MVI.PRICE,MVI.NETPRICE,MVI.M_DURATION,MVI.BPYIELD,MVI.LAST_PERIOD,rank() OVER(PARTITION BY MVI.SEC_ID ORDER BY MVI.VALUE_DATE DESC ) AS rowno
from MST_BOND_VALUATION_INFO MVI
INNER JOIN FIN_PRODUCT FP ON MVI.SEC_ID=FP.FINPROD_MARKET_ID
 WHERE MVI.VALUE_DATE <= #{valDate, jdbcType=DATE}

	and FP.FINPROD_ID in

		#{item}


) WHERE ROWNO =1

select PORTFOLIO_ID,sum(TDY_ASSET_NETVALUE) TDY_ASSET_NETVALUE,sum(TDY_ASSET_VALUE) TDY_ASSET_VALUE from ( SELECT PORTFOLIO_ID,TDY_ASSET_NETVALUE,TDY_ASSET_VALUE FROM ( SELECT PORTFOLIO_ID,TDY_ASSET_NETVALUE,TDY_ASSET_VALUE, RANK() OVER(PARTITION BY PORTFOLIO_ID ORDER BY CDATE desc) AS rowno FROM PTL_PORTFOLIO_VALUATION ppv WHERE CDATE <= #{valDate, jdbcType=DATE}-1 and nvl(TDY_ASSET_NETVALUE,0)>0
and PORTFOLIO_ID in
#{item}
) WHERE ROWNO =1 union all SELECT fp.finprod_market_id,trade_amt*decode(tpd.ps,'C4',-1,'C17',-1,'C6',-1,'C5',-1,'C20',-1,'C1',1,'C2',1,'C3',1,0) TDY_ASSET_NETVALUE ,trade_amt*decode(tpd.ps,'C4',-1,'C17',-1,'C6',-1,'C5',-1,'C20',-1,'C1',1,'C2',1,'C3',1,0) TDY_ASSET_VALUE FROM trd_product_deal tpd left join fin_product fp on fp.finprod_id = tpd.finprod_id where fp.finprod_type2 = 'F16' and tpd.settle_date = #{valDate, jdbcType=DATE} and tpd.trade_status = '01' and tpd.is_cancel = 'N'
and fp.finprod_market_id in
#{item}
) group by PORTFOLIO_ID

SELECT distinct A.PORTFOLIO_ID , A.ACCT_NO , B.REGIST_ORG , B.TRADE_PLACE FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
and A.PORTFOLIO_ID in
#{item}
AND B.TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}
AND B.REGIST_ORG = #{registOrg, jdbcType=VARCHAR}
